USE order_payment;
CREATE TABLE IF NOT EXISTS pay_order(id BIGINT PRIMARY KEY,pay_order_no VARCHAR(64) NOT NULL,biz_order_no VARCHAR(64) NOT NULL,user_id BIGINT NOT NULL,amount_cent BIGINT NOT NULL,status TINYINT NOT NULL,channel_code VARCHAR(32) NOT NULL,channel_trade_no VARCHAR(128),pay_time DATETIME(3),version INT NOT NULL DEFAULT 0,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uk_pay_order_no(pay_order_no),UNIQUE KEY uk_biz_order_no(biz_order_no),KEY idx_user_time(user_id,create_time)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pay_notify_log(id BIGINT PRIMARY KEY,notify_id VARCHAR(64) NOT NULL,pay_order_no VARCHAR(64) NOT NULL,channel_code VARCHAR(32) NOT NULL,notify_payload TEXT NOT NULL,process_status TINYINT NOT NULL,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uk_notify_id(notify_id),KEY idx_pay_order_no(pay_order_no)) ENGINE=InnoDB;
